    t3_b1: "Three words rhyme.",
    t3_b2: "One word sounds completely different.",
    t3_inst: "Find the word that does NOT rhyme!",
    t3_h1: "Three words end in '-ose'.",
    t3_h2: "'Tree' does not rhyme with pants, rose, and can.",
