    t5_title: "Short Rhymes",
    t5_text: "Small words can rhyme too! Tea ☕ and sea 🌊 are only three letters long, but a perfect rhyme pair.",
    t5_b1: "Sea rhymes with tea.",
    t5_b2: "Ice rhymes with hot.",
    t5_inst: "Which word rhymes with 'ice'?",
    t5_h1: "It ends with the same sound.",
    t5_h2: "Ice - hot.",
    t5_w1: "cold",
