    t5_qd: "Fish",
    t6_title: "Picture Rhymes",
    t6_text: "Sometimes we don't have letters, only pictures. But when we say them out loud, we hear the rhyme!",
    t6_b1: "Say the picture out loud.",
    t6_b2: "👑 (Crown) rhymes with 🍋 (Lemon).",
