    t8_qd: "Day",
    t9_title: "Beginning Rhymes (Alliteration)",
    t9_text: "Sometimes words start with the same letter. That's called alliteration! Example: 'Bold bears build bridges.'",
    t9_b1: "All words begin with 'B'.",
    t9_b2: "That sounds funny and rhythmic.",
