    t9_qa: "Storm",
    t9_qb: "Rain",
    t9_qc: "Moon",
    t9_qd: "Night",
    t10_title: "Slow and Fast Rhymes",
    t10_text: "Some rhymes are close together (fast rhymes). Some are far apart (slow rhymes). Both sound beautiful!",
