    t10_qb: "Fast rhyme",
    t10_qc: "Double rhyme",
    t10_qd: "Broken rhyme",
    t11_title: "Funny Fake Rhymes",
    t11_text: "Some words look like they rhyme, but they don't! Or they sound like they rhyme, but it's a trick!",
    t11_b1: "Fake rhymes look or sound wrong.",
    t11_b2: "Example: 'Laughing' and 'roofing' (No!).",
