    t13_title: "Rhymes in Names",
    t13_text: "Even names can rhyme! Michael and Chantal? No. But Anna and Hanna? Yes! Maybe your best friend has a name that rhymes with yours!",
    t13_b1: "Many names can rhyme.",
    t13_b2: "Anna - Hanna, Paul - Saul.",
