    t1_w2: "se",
    t1_w3: "joacă",
    t1_w4: "în",
    t1_w5: "grădină.",
    t1_q: "Cum se termină o propoziție enunțiativă normală?",
    t1_qa: "Cu un punct (.)",
    t1_qb: "Cu o virgulă (,)",
    t1_qc: "Cu un număr",
    t1_qd: "Deloc",
    t2_title: "Sfârșitul propoziției (Punctul)",
    t2_text: "Punctul (.) ne spune: 'Aici propoziția s-a terminat. Fă o mică pauză la citire!'",
    t2_b1: "Punctul (.) încheie propoziția.",
    t2_inst: "Unde se pune punctul?",
    t2_h1: "Punctul se pune mereu la final.",
    t2_h2: "După cuvântul 'doarme', propoziția se termină.",
    t2_w1: "Pisica",
    t2_w2: "doarme",
    t2_w3: "acum",
    t2_w4: ".",
    t2_q: "Unde se află semnul de punctuație?",
    t2_qa: "La sfârșitul propoziției",
    t2_qb: "La început",
    t2_qc: "În mijloc",
    t2_qd: "Sub cuvânt",
    t3_title: "Propoziții interogative (?)",
    t3_text: "Când vrem să știm ceva, punem o întrebare. Atunci folosim un semn de întrebare (?). Vocea urcă la final!",
    t3_b1: "Întrebările se termină cu (?)",
    t3_b2: "Cine? Cum? Ce? Unde?",
    t3_inst: "Ce semn de punctuație se potrivește aici: 'Ce mai faci'?",
    t3_h1: "Aceasta este o întrebare, deci avem nevoie de semnul de întrebare.",
    t3_h2: "Semnul (?) este corect.",
    t3_w1: ".",
    t3_w2: "?",
    t3_w3: "!",
    t3_w4: ",",
    t3_q: "Ce cuvânt începe adesea o întrebare?",
    t3_qa: "Cine",
    t3_qb: "și",
    t3_qc: "este",
    t3_qd: "nu",
    t4_title: "Ordonarea cuvintelor",
    t4_text: "Într-o propoziție, cuvintele nu trebuie să fie amestecate! Ele trebuie să fie în ordinea corectă pentru a le putea înțelege.",
    t4_b1: "Ordinea este importantă.",
    t4_b2: "Eu - mănânc - măr (Corect!). Măr - eu - mănânc (Greșit!).",
    t4_inst: "Care propoziție este construită corect?",
    t4_h1: "Cine ce face? 'Eu mă joc cu mingea.'",
    t4_h2: "'Eu mă joc cu mingea' are sens.",
    t4_w1: "Eu mă joc cu mingea.",
    t4_w2: "Mingea mă joc eu.",
