    t4_w4: "Eu mingea mă joc.",
    t4_q: "Ce se întâmplă când schimbi ordinea cuvintelor într-o propoziție?",
    t4_qa: "Propoziția este greu de înțeles",
    t4_qb: "Nu se întâmplă nimic",
    t4_qc: "Literele devin mai mici",
    t4_qd: "Punctul dispare",
    t5_title: "Punct sau semn de întrebare?",
    t5_text: "Povestim ceva (punct) sau întrebăm ceva (semn de întrebare)? Tu trebuie să decizi!",
    t5_b1: "Afirmație = Punct (.)",
    t5_b2: "Întrebare = Semn de întrebare (?)",
    t5_inst: "Sortează: Se pune un punct sau un semn de întrebare la final?",
    t5_h1: "Este o informație sau o întrebare?",
    t5_h2: "'Eu sunt înalt.' (Punct). 'Tu ești înalt?' (Semn de întrebare).",
